# >>> HINTS
# <<< HINTS

# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_plugin() {
    _argc_util_cache 3600 _helper_plugin_uncached "ansible-doc_${argc_type:-module}"
}

_helper_plugin_uncached() {
    local type="${argc_type:-module}" json
    json="$(ansible-doc -l -t "$type" -j 2>/dev/null)"
    if [[ -n "$json" ]]; then
        printf '%s\n' "$json" |
            jq -b -r 'to_entries[] | .key + "\t" + ((if (.value | type) == "string" then .value else (.value.description // "") end) | gsub("[\t\n\r]"; " "))'
        return 0
    fi
    # Broken collection metadata can make --list fail; --list_files still works.
    case "$type" in
    role) ;;
    keyword) ansible-doc -F -t keyword 2>/dev/null | sed -n 's/^\([A-Za-z0-9_.]*\):.*/\1/p' ;;
    *) ansible-doc -F -t "$type" 2>/dev/null | gawk '{ print $1 }' ;;
    esac
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
